    def parse_characteristics(characteristics):
        """
        Recursively parses nested dictionaries to return a dictionary of characteristics.

        :param characteristics: Dictionary of characteristics.
        :return: Dictionary of characteristics with nested dictionaries parsed.
        """
        parsed_characteristics = {}
        for key, value in characteristics.items():
